import java.io.*;
import java.util.*;

public class Main implements Runnable {
    static final int MOD = (int) 1e9 + 7;
    static final int MI = (int) 1e9;
    static final long ML = (long) 1e18;
    static final Reader in = new Reader();
    static final PrintWriter out = new PrintWriter(System.out);
    StringBuilder outputBuffer = new StringBuilder();

    public static void main(String[] args) {
        new Thread(null, new Main(), "persefone", 1 << 32).start();
    }

    @Override
    public void run() {
        runSolution();
        displayOutput();
        terminate();
    }

    void runSolution() {
        int w = in.nextInt();
        int m = in.nextInt();
        if (w <= 3) {
            appendOutput("YES");
            return;
        }

        long limit = (long) 1e10;
        long val = 1;
        List<Long> powersList = new ArrayList<>();
        do {
            powersList.add(val);
            val *= w;
        } while (val <= limit);

        long[] arr = powersList.stream().mapToLong(Long::longValue).toArray();
        int n = arr.length;
        for (int mask = 0; mask < (1 << n); mask++) {
            long sum = m;
            for (int bit = 0; bit < n; bit++) {
                if ((mask & (1 << bit)) != 0) {
                    sum += arr[bit];
                }
            }
            for (int bit = n - 1; bit >= 0; bit--) {
                if ((mask & (1 << bit)) == 0) {
                    if (sum - arr[bit] >= 0) {
                        sum -= arr[bit];
                    }
                }
            }
            if (sum == 0) {
                appendOutput("YES");
                return;
            }
        }
        appendOutput("NO");
    }

    void displayOutput() {
        out.print(outputBuffer);
    }

    void appendOutput(String s) {
        outputBuffer.append(s);
    }

    void terminate() {
        out.close();
    }
}
